package org.circus.core;
import java.io.*;
import java.util.*;
import java.util.zip.InflaterInputStream;
/** CurrentDC2 complete rain programs against independently interpretedx86.
 * Required graphics leaves are explicit call journals, not rendered output. */
public final class Dc2RainTests {
 private static int count;private static void check(boolean v,String why){count++;if(!v)throw new AssertionError(why);}
 private static byte[] blob(DataInput in)throws IOException{int n=in.readInt();if(n<0||n>1024*1024)throw new IOException("fixture size");byte[] raw=new byte[n];in.readFully(raw);return raw;}
 private static final class Image {byte[] records;int level,handle,rng;List<int[]> events=new ArrayList<>();}
 private static Image image(DataInput in)throws IOException{Image s=new Image();s.records=blob(in);s.level=in.readInt();s.handle=in.readInt();s.rng=in.readInt();int n=in.readInt();for(int k=0;k<n;k++){int address=in.readInt(),length=in.readInt();int[] event=new int[length+1];event[0]=address;for(int i=0;i<length;i++)event[i+1]=in.readInt();s.events.add(event);}return s;}
 private static final class Owner implements Dc2Rain.State,Dc2Rain.Random,Dc2Rain.Services {
  final byte[] records;int level,handle,rng,result;final List<int[]> events=new ArrayList<>();
  Owner(Image image,int result){records=image.records.clone();level=image.level;handle=image.handle;rng=image.rng;this.result=result;}
  public int read(int address)throws IOException{if(address==Dc2Rain.LEVEL)return level;if(address==Dc2Rain.HANDLE)return handle;int at=address-Dc2Rain.RECORDS;if(at<0||at+4>records.length)throw new IOException("unknown rain byte");return(records[at]&255)|(records[at+1]&255)<<8|(records[at+2]&255)<<16|records[at+3]<<24;}
  public void write(int address,int value)throws IOException{if(address==Dc2Rain.LEVEL){level=value;return;}if(address==Dc2Rain.HANDLE){handle=value;return;}int at=address-Dc2Rain.RECORDS;if(at<0||at+4>records.length)throw new IOException("unknown rain byte");for(int n=0;n<4;n++)records[at+n]=(byte)(value>>>(n*8));}
  public int next(){rng=rng*214013+2531011;return rng>>>16&32767;}
  public int loadImage(int address,int mode){events.add(new int[]{0x401cc0,address,mode});return result;}
  public void freeImage(int handle){events.add(new int[]{0x401130,handle});}
  public void clip(int l,int t,int r,int b){events.add(new int[]{0x407f40,l,t,r,b});}
  public void restore(int l,int t,int r,int b){events.add(new int[]{0x411840,l,t,r,b});}
  public void controls(int mode,int l,int t,int r,int b){events.add(new int[]{0x41d3f0,mode,l,t,r,b});}
  public void blend(int x,int y,int handle,int weight){events.add(new int[]{0x408b80,x,y,handle,weight});}
 }
 public static int run()throws Exception{
  count=0;StringBuilder encoded=new StringBuilder();for(String s:VECTORS)encoded.append(s);DataInputStream in=new DataInputStream(new InflaterInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(encoded.toString()))));int programs=in.readInt();
  for(int n=0;n<programs;n++){String id=new String(blob(in),"UTF-8");int result=in.readInt(),operations=in.readInt();int[][] ops=new int[operations][2];for(int[] op:ops){op[0]=in.readInt();op[1]=in.readInt();}Image initial=image(in),expected=image(in);Owner owner=new Owner(initial,result);
   for(int[] op:ops)switch(op[0]){case 0:Dc2Rain.initialize(owner,owner,owner,op[1]);break;case 1:Dc2Rain.update(owner,owner);break;case 2:Dc2Rain.draw(owner,owner,op[1]);break;case 3:Dc2Rain.release(owner,owner);break;default:throw new IOException("fixture op");}
   check(Arrays.equals(owner.records,expected.records),id+" entire80-record backing including stale suffix");check(owner.level==expected.level&&owner.handle==expected.handle,id+" raw native level/handle");check(owner.rng==expected.rng,id+" exact shared CRT consumption");boolean same=owner.events.size()==expected.events.size();for(int k=0;same&&k<owner.events.size();k++)same=Arrays.equals(owner.events.get(k),expected.events.get(k));check(same,id+" exact required-leaf sequence/arguments");
  }
  check(in.read()==-1,"rain vector trailer");
  return count;
 }
 public static void main(String[] args)throws Exception{System.out.println("PASS "+run()+" nativeDC2 rain checks");}
 private static final String[] VECTORS={
        "",
        "",
        "",
        ""
 };
}
